module viterbi_decoder(  
    input wire clk,  
    input wire reset,  
    input wire received_bit,  
    output reg decoded_bit  
);  
    // State encoding  
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;  
    reg [1:0] current_state, next_state;  

    // Sequential logic for state transitions  
    always @(posedge clk or posedge reset) begin  
        if (reset)  
            current_state <= S0;  
        else  
            current_state <= next_state;  
    end  

    // Combinational logic for next state and output  
    always @(*) begin  
        case (current_state)  
            S0: begin  
                if (received_bit) begin  
                    next_state = S1;  
                    decoded_bit = 1'b0;  
                end else begin  
                    next_state = S2;  
                    decoded_bit = 1'b1;  
                end  
            end  
            S1: begin  
                if (received_bit) begin  
                    next_state = S3;  
                    decoded_bit = 1'b0;  
                end else begin  
                    next_state = S0;  
                    decoded_bit = 1'b1;  
                end  
            end  
            S2: begin  
                if (received_bit) begin  
                    next_state = S0;  
                    decoded_bit = 1'b1;  
                end else begin  
                    next_state = S1;  
                    decoded_bit = 1'b0;  
                end  
            end  
            S3: begin  
                if (received_bit) begin  
                    next_state = S2;  
                    decoded_bit = 1'b1;  
                end else begin  
                    next_state = S0;  
                    decoded_bit = 1'b0;  
                end  
            end  
            default: begin  
                next_state = S0;  
                decoded_bit = 1'b0;  
            end  
        endcase  
    end  
endmodule

