module watchdog_timer (
    input wire clk,
    input wire rst_n,
    output reg timeout
);
    reg [3:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 4'b0000;
            timeout <= 1'b0;
        end else if (counter == 4'b1111) begin
            timeout <= 1'b1; // Timer expired
        end else begin
            counter <= counter + 1;
            timeout <= 1'b0; // Timer not expired
        end
    end
endmodule

