module stop_and_wait (
    input clk,
    input rst,
    input send_data,
    input ack,
    output reg data_out,
    output reg busy,
    output reg timeout
);
    parameter IDLE = 2'b00, SENDING = 2'b01, WAITING_ACK = 2'b10;
    reg [1:0] state, next_state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        next_state = state;
        busy = 0;
        timeout = 0;

        case (state)
            IDLE: begin
                if (send_data) begin
                    next_state = SENDING;
                    data_out = 1; // Sending data
                    busy = 1;
                end
            end
            SENDING: begin
                busy = 1;
                if (ack) begin
                    next_state = IDLE;
                end else begin
                    timeout = 1; // Simulate timeout for ACK
                end
            end
            WAITING_ACK: begin
                busy = 1;
                if (ack) begin
                    next_state = IDLE;
                end else begin
                    timeout = 1; // Simulate timeout for ACK
                end
            end
        endcase
    end
endmodule

