module carrier_frequency_recovery (
    input wire clk,
    input wire reset,
    input wire modulated_signal,
    output reg recovered_frequency,
    output reg lock_indicator
);
    reg [3:0] phase;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            phase <= 0;
            recovered_frequency <= 0;
            lock_indicator <= 0;
        end else begin
            phase <= phase + (modulated_signal ? 1 : -1);
            if (phase == 4'b1111) begin
                lock_indicator <= 1;
                recovered_frequency <= 1;
            end else if (phase == 4'b0000) begin
                lock_indicator <= 1;
                recovered_frequency <= 0;
            end else begin
                lock_indicator <= 0;
            end
        end
    end
endmodule

