module crc_generator (
    input wire clk,
    input wire rst,
    input wire [31:0] data_in,
    input wire [31:0] polynomial,
    input wire start,
    output reg [31:0] crc_out,
    output reg done
);
    reg [31:0] crc;
    reg [5:0] bit_count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            crc <= 32'b0;
            crc_out <= 32'b0;
            done <= 0;
            bit_count <= 6'b0;
        end
        else if (start) begin
            crc <= data_in;
            bit_count <= 6'b0;
            done <= 0;
        end
        else if (bit_count < 32) begin
            if (crc[31] == 1'b1) begin
                crc <= (crc << 1) ^ polynomial;
            end else begin
                crc <= crc << 1;
            end
            bit_count <= bit_count + 1;
        end
        else begin
            crc_out <= crc;
            done <= 1;
        end
    end
endmodule

