module watchdog_timer(
    input wire clk,
    input wire reset,
    input wire kick,
    input wire [3:0] timeout, // timeout duration in clock cycles
    output reg safe_state // 1 if safe, 0 if in reset state
);
    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            safe_state <= 1;
        end else if (kick) begin
            counter <= 0;
            safe_state <= 1;
        end else begin
            if (counter < timeout) begin
                counter <= counter + 1;
            end else begin
                safe_state <= 0; // enter reset state
            end
        end
    end
endmodule

