module watchdog_timer(  
    input clk,  
    input rst_n,  
    input reset_signal,  
    output reg timeout  
);  
    parameter TIMEOUT_COUNT = 4'b1010; // Set to 10 for example  
    reg [3:0] counter;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            counter <= 4'b0000;  
            timeout <= 1'b0;  
        end else begin  
            if (reset_signal) begin  
                counter <= 4'b0000;  
                timeout <= 1'b0;  
            end else begin  
                if (counter < TIMEOUT_COUNT)  
                    counter <= counter + 1;  
                else  
                    timeout <= 1'b1;  
            end  
        end  
    end  
endmodule

