module butterworth_filter(clk, reset, sample_in, sample_out);  
    input clk, reset;  
    input [3:0] sample_in;  
    output reg [3:0] sample_out;  

    reg [3:0] x_reg [0:1]; // Input samples  
    reg [3:0] y_reg [0:1]; // Output samples  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            x_reg[0] <= 4'b0000;  
            x_reg[1] <= 4'b0000;  
            y_reg[0] <= 4'b0000;  
            y_reg[1] <= 4'b0000;  
            sample_out <= 4'b0000;  
        end else begin  
            x_reg[1] <= x_reg[0];  
            x_reg[0] <= sample_in;  
            y_reg[1] <= y_reg[0];  
            y_reg[0] <= (x_reg[0] + x_reg[1] + y_reg[1]) >> 1; // Basic output calculation  
            sample_out <= y_reg[0];  
        end  
    end  
endmodule

