module FFT (
    input wire clk,
    input wire start,
    input wire [3:0] real_in,
    input wire [3:0] imag_in,
    output reg [3:0] real_out,
    output reg [3:0] imag_out,
    output reg valid
);
    reg [2:0] state;
    reg [3:0] real_buf [0:7];
    reg [3:0] imag_buf [0:7];
    integer i;

    always @(posedge clk) begin
        if (start) begin
            // Initialize state and buffers
            state <= 0;
            valid <= 0;
            for (i = 0; i < 8; i = i + 1) begin
                real_buf[i] <= 0;
                imag_buf[i] <= 0;
            end
            real_buf[state] <= real_in;
            imag_buf[state] <= imag_in;
        end else if (state < 7) begin
            // Perform FFT step (for simplicity, not a real FFT implementation)
            state <= state + 1;
            real_buf[state] <= real_buf[state - 1] + imag_buf[state - 1]; // Fake calculation
            imag_buf[state] <= imag_buf[state - 1] - real_buf[state - 1]; // Fake calculation
        end else if (state == 7) begin
            // Output the result
            real_out <= real_buf[state];
            imag_out <= imag_buf[state];
            valid <= 1;
        end
    end
endmodule

