module i2c_master  
(  
    input wire clk,  
    input wire rst,  
    input wire start,  
    input wire [7:0] data_in,  
    output reg sda,  
    output reg scl,  
    output reg ack,  
    output reg busy  
);  

reg [3:0] state;  
reg [3:0] bit_cnt;  
reg [7:0] data_reg;  

localparam IDLE = 4'b0000,  
           START = 4'b0001,  
           SEND = 4'b0010,  
           ACK_CHECK = 4'b0011,  
           RECEIVE = 4'b0100,  
           STOP = 4'b0101;  

always @(posedge clk or posedge rst)  
begin  
    if (rst)  
    begin  
        state <= IDLE;  
        scl <= 1;  
        sda <= 1;  
        busy <= 0;  
        ack <= 0;  
    end  
    else  
    begin  
        case (state)  
            IDLE:  
            begin  
                if (start)  
                begin  
                    data_reg <= data_in;  
                    bit_cnt <= 0;  
                    busy <= 1;  
                    state <= START;  
                end  
            end  
            START:  
            begin  
                sda <= 0;  
                scl <= 0;  
                state <= SEND;  
            end  
            SEND:  
            begin  
                if (bit_cnt < 8)  
                begin  
                    sda <= data_reg[7 - bit_cnt];  
                    scl <= 0;  
                    bit_cnt <= bit_cnt + 1;  
                    scl <= 1;  
                end  
                else  
                begin  
                    state <= ACK_CHECK;  
                end  
            end  
            ACK_CHECK:  
            begin  
                scl <= 0;  
                ack <= sda;  
                scl <= 1;  
                state <= STOP;  
            end  
            STOP:  
            begin  
                sda <= 0;  
                scl <= 1;  
                sda <= 1;  
                busy <= 0;  
                state <= IDLE;  
            end  
        endcase  
    end  
end  
endmodule

