module IIR_Filter (
    input clk,
    input reset,
    input signed [15:0] x_in,
    output reg signed [15:0] y_out
);
    // Filter coefficients
    parameter signed [15:0] b0 = 16'h0A00, b1 = 16'h0B00, b2 = 16'h0C00;
    parameter signed [15:0] a1 = 16'hF500, a2 = 16'hF600;

    reg signed [15:0] x1, x2; // Previous inputs
    reg signed [15:0] y1, y2; // Previous outputs

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            x1 <= 16'd0;
            x2 <= 16'd0;
            y1 <= 16'd0;
            y2 <= 16'd0;
            y_out <= 16'd0;
        end else begin
            y_out <= (b0 * x_in + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2) >>> 8;
            // Update previous inputs and outputs
            x2 <= x1;
            x1 <= x_in;
            y2 <= y1;
            y1 <= y_out;
        end
    end
endmodule

