module PLL (
    input wire clk_in,
    input wire reset,
    output reg clk_out
);
    reg [3:0] phase_counter; // 4-bit phase counter
    reg vco_output; // VCO output signal

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            phase_counter <= 4'b0000;
            vco_output <= 1'b0;
            clk_out <= 1'b0;
        end else begin
            phase_counter <= phase_counter + 1;
            if (phase_counter == 4'b1111) begin
                vco_output <= ~vco_output; // toggle VCO output
            end
            clk_out <= vco_output;
        end
    end
endmodule

