module divide_by_4 (  
    input clk,  
    input rst,  
    output reg [1:0] out  
);  
    reg [3:0] count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 0;  
            out <= 0;  
        end else begin  
            count <= count + 1;  
            if (count == 4) begin  
                out <= out + 1;  
                count <= 0;  
            end  
        end  
    end  
endmodule

