module restoring_divider #(parameter N = 8) (  
    input clk,  
    input rst,  
    input [N-1:0] dividend,  
    output reg [N-1:0] quotient,  
    output reg [N-1:0] remainder,  
    output reg ready  
);  
    reg [N-1:0] divisor = 3;  
    reg [N-1:0] temp;  
    reg [N-1:0] count;  
    reg state;  

    parameter IDLE = 1'b0, DIVIDE = 1'b1;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            quotient <= 0;  
            remainder <= 0;  
            temp <= 0;  
            count <= 0;  
            ready <= 0;  
            state <= IDLE;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (dividend != 0) begin  
                        temp <= dividend;  
                        quotient <= 0;  
                        count <= N;  
                        state <= DIVIDE;  
                    end  
                end  
                DIVIDE: begin  
                    temp <= {temp[N-2:0], 1'b0}; // Shift left  
                    if (temp >= divisor) begin  
                        temp <= temp - divisor;  
                        quotient <= {quotient[N-2:0], 1'b1};  
                    end else begin  
                        quotient <= {quotient[N-2:0], 1'b0};  
                    end  
                    if (count == 1) begin  
                        remainder <= temp;  
                        ready <= 1;  
                        state <= IDLE;  
                    end else begin  
                        count <= count - 1;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

