module rs_encoder(  
    input clk,  
    input start,  
    input [3:0] data_in,  
    output reg [6:0] encoded_out,  
    output reg ready  
);  
    reg [3:0] data_reg;  
    reg [2:0] state;  

    parameter IDLE = 3'b000, LOAD = 3'b001, ENCODE = 3'b010, OUTPUT = 3'b011;  

    always @(posedge clk) begin  
        case (state)  
            IDLE: begin  
                ready <= 1'b0;  
                if (start) begin  
                    state <= LOAD;  
                end  
            end  
            LOAD: begin  
                data_reg <= data_in;  
                state <= ENCODE;  
            end  
            ENCODE: begin  
                // Simple encoding logic (for example purpose)  
                encoded_out <= {data_reg, data_reg[3:2] ^ data_reg[1:0]};  
                state <= OUTPUT;  
            end  
            OUTPUT: begin  
                ready <= 1'b1;  
                state <= IDLE;  
            end  
        endcase  
    end  
endmodule

