module ofdm_modulator (
    input clk,
    input reset,
    input [15:0] data_in,
    output reg [15:0] tx_out
);
    reg [3:0] symbol [0:3];
    reg [15:0] ifft_out;
    reg [15:0] cyclic_prefix;

    // QPSK mapping
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx_out <= 16'b0;
        end else begin
            // Map the input bits to QPSK symbols
            symbol[0] = {data_in[3:2], 1'b0};
            symbol[1] = {data_in[1:0], 1'b0};
            // Assume a simple IFFT operation represented by concatenation for this example
            ifft_out = {symbol[0], symbol[1]} << 2;  // Simple representation of IFFT
            cyclic_prefix = ifft_out[15:12]; // Get the last 4 samples for cyclic prefix
            tx_out = {cyclic_prefix, ifft_out}; // Append cyclic prefix to IFFT output
        end
    end
endmodule

