module dram_cell(  
    input [3:0] data,  
    input read,  
    input write,  
    output reg [3:0] stored_data  
);  

    always @(posedge write or posedge read) begin  
        if (write)  
            stored_data <= data;  
    end  

    always @(posedge read) begin  
        if (read)  
            stored_data <= stored_data;  
    end  
endmodule

