module pitch_detection(
    input wire clk,
    input wire reset,
    input wire audio_signal,
    output reg [15:0] detected_pitch
);
    reg [15:0] pitch_counter;
    reg [15:0] last_pitch;
    reg valid_pitch;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pitch_counter <= 0;
            detected_pitch <= 0;
            last_pitch <= 0;
            valid_pitch <= 0;
        end else begin
            if (audio_signal) begin
                pitch_counter <= pitch_counter + 1;
                valid_pitch <= 1;
            end else begin
                if (valid_pitch) begin
                    detected_pitch <= pitch_counter;
                    last_pitch <= pitch_counter;
                    pitch_counter <= 0;
                    valid_pitch <= 0;
                end else begin
                    pitch_counter <= 0;
                end
            end
        end
    end
endmodule

