module Comparator16Bit(  
    input [15:0] A,  
    input [15:0] B,  
    output reg A_gt_B,  
    output reg A_eq_B,  
    output reg A_lt_B  
);  
    always @(*) begin  
        A_gt_B = 0;  
        A_eq_B = 0;  
        A_lt_B = 0;  

